// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 blockNum) public {
        bound(blockNum, 1, type(uint256).max);
        vm.assume(amount >= 10 ether);

        address caller1 = address(0x100);
        address caller2 = address(0x200);

        vm.roll(blockNum);

        vm.deal(caller1, amount);
        vm.prank(caller1);
        (bool ok1,) = address(c).call{value: 10 ether}("");

        vm.deal(caller2, amount);
        vm.prank(caller2);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(!(ok1 && ok2));
    }
}
